INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u2_L07_challenge#3','math',6,2,'u2','L07','g6_2_math_u2_L07_challenge','lesson_challenge','M6-2-u2-C6',3,'error','auto','세 판을 보고 쌓은 모양을 떠올리는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u2-X06','M6-2-u2-X18']::text[],false,'{"seq":3,"concept":"M6-2-u2-C6","difficulty":3,"kind":"error","stem":"세 판을 보고 쌓은 모양을 떠올리는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도영 — 「앞에서 본 모양은 줄마다 쌓기나무가 몇 개인지 알려 줘.」","correct":true,"mis_target":"M6-2-u2-X06"},{"t":"나린 — 「위에서 본 모양으로 먼저 1층을 깔아.」","mis":"M6-2-u2-X18"},{"t":"하람 — 「앞과 옆에서 본 모양은 줄마다 가장 높은 층을 알려 줘.」","mis":"M6-2-u2-X18"}],"explanation":["앞에서 보면 줄마다 가장 높은 층까지만 보여요.","그 줄에 쌓기나무가 몇 개인지는 알 수 없어요.","도영이는 가장 높은 층을 개수로 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
